t.script:
function filterByChauffeur(chauffeur) {
  const url = new URL(window.location);
  if (chauffeur) { url.searchParams.set('chauffeur', chauffeur); }
  else { url.searchParams.delete('chauffeur'); }
  url.searchParams.set('limit', '1000');
  window.location.href = url.toString();
}

function filterByClient(client) {
  const url = new URL(window.location);
  if (client) { url.searchParams.set('client', client); }
  else { url.searchParams.delete('client'); }
  url.searchParams.set('limit', '1000');
  window.location.href = url.toString();
}

function toggleDemandes() {
  const content = document.getElementById('demandesContent');
  const btn = document.getElementById('toggleBtn');

  if (content.style.display === 'none') {
    content.style.display = 'block';
    btn.innerHTML = '<span class="d-none d-md-inline">Masquer</span><span class="d-md-none">Masquer</span>';
  } else {
    content.style.display = 'none';
    btn.innerHTML = '<span class="d-none d-md-inline">Afficher</span><span class="d-md-none">Voir</span>';
  }
  if(window.fitGrid){ setTimeout(window.fitGrid, 30); }
}

function applyFilters(){
  var hideTP = localStorage.getItem('tpHidden') === '1';
  var st = localStorage.getItem('tpStatus') || '';
  document.querySelectorAll('.tp-card').forEach(function(c){
    var show = true;
    if(hideTP && c.getAttribute('data-tp') === '1'){ show = false; }
    if(st && c.getAttribute('data-status') !== st){ show = false; }
    c.style.display = show ? '' : 'none';
  });
  var btn = document.getElementById('tpToggleBtn');
  if(btn){ btn.innerHTML = hideTP ? '🏗️ Afficher TP' : '🏗️ Masquer TP'; }
  var sel = document.getElementById('statusFilter');
  if(sel){ sel.value = st; }
  tpRenderCounts();
}
function tpComputeCounts(){
  var desktop = window.matchMedia('(min-width: 768px)').matches;
  var scope = document.getElementById(desktop ? 'tpDesktop' : 'tpMobile') || document;
  var cards = scope.querySelectorAll('.tp-card');
  var hideTP = localStorage.getItem('tpHidden') === '1';
  var c = {facture:0, paye:0, brouillon:0, afacturer:0, annule:0, autre:0, total:0};
  cards.forEach(function(card){
    if(hideTP && card.getAttribute('data-tp') === '1'){ return; }
    var s = card.getAttribute('data-status') || 'autre';
    if(c[s] === undefined){ s = 'autre'; }
    c[s]++; c.total++;
  });
  return c;
}
function tpRenderCounts(){
  var bar = document.getElementById('tpCountBar');
  if(!bar){ return; }
  var c = tpComputeCounts();
  var st = localStorage.getItem('tpStatus') || '';
  var defs = [['','🏷️ Tous','#334155',c.total],
    ['facture','✅ Facturé','#198754',c.facture],
    ['paye','💰 Payé','#0d6efd',c.paye],
    ['brouillon','🧾 Brouillon','#eab308',c.brouillon],
    ['afacturer','🧾 À facturer','#fd7e14',c.afacturer],
    ['annule','❌ Annulé','#dc3545',c.annule],
    ['autre','⬜ Sans statut','#6c757d',c.autre]];
  bar.innerHTML = '';
  defs.forEach(function(d){
    var active = (d[0] === st) || (d[0] === '' && !st);
    var chip = document.createElement('span');
    chip.style.cssText = 'cursor:pointer;border:1.5px solid ' + d[2] + ';border-radius:14px;padding:2px 10px;font-size:12px;font-weight:700;' + (active ? ('background:' + d[2] + ';color:#fff;') : ('background:#fff;color:' + d[2] + ';'));
    chip.textContent = d[1] + '  ' + d[3];
    chip.addEventListener('click', function(){ filterByStatus(d[0]); });
    bar.appendChild(chip);
  });
}
function toggleTP(){ localStorage.setItem('tpHidden', localStorage.getItem('tpHidden') === '1' ? '0' : '1'); applyFilters(); }
function filterByStatus(v){ localStorage.setItem('tpStatus', v); applyFilters(); }
window.addEventListener('DOMContentLoaded', applyFilters);
window.addEventListener('resize', tpRenderCounts);

// Gestion du bandeau fixe
window.addEventListener('DOMContentLoaded', function() {
  const mainTable = document.getElementById('mainTable');
  const stickyHeader = document.getElementById('stickyHeader');

  if (!mainTable || !stickyHeader) return;

  const thead = mainTable.querySelector('thead');
  const tableContainer = mainTable.closest('.table-responsive');

  if (!thead || !tableContainer) return;

  const theadRect = thead.getBoundingClientRect();
  const theadTop = theadRect.top + window.scrollY;

  function syncColumnWidths() {
    const tableHeaders = thead.querySelectorAll('th');
    const stickyHeaders = stickyHeader.querySelectorAll('.header-cell');

    tableHeaders.forEach((th, index) => {
      if (stickyHeaders[index]) {
        const width = th.offsetWidth;
        stickyHeaders[index].style.width = width + 'px';
        stickyHeaders[index].style.minWidth = width + 'px';
        stickyHeaders[index].style.maxWidth = width + 'px';
      }
    });

    const stickyContent = stickyHeader.querySelector('.d-flex');
    if (stickyContent) {
      stickyContent.style.width = mainTable.offsetWidth + 'px';
    }

    const tableRect = tableContainer.getBoundingClientRect();
    stickyHeader.style.left = tableRect.left + 'px';
    stickyHeader.style.right = (window.innerWidth - tableRect.right) + 'px';
  }

  syncColumnWidths();
  setTimeout(syncColumnWidths, 100);
  setTimeout(syncColumnWidths, 500);

  window.addEventListener('resize', syncColumnWidths);

  window.addEventListener('scroll', function() {
    if (window.scrollY > theadTop) {
      stickyHeader.style.display = 'block';
      syncColumnWidths();
    } else {
      stickyHeader.style.display = 'none';
    }
  });

  tableContainer.addEventListener('scroll', function() {
    stickyHeader.scrollLeft = tableContainer.scrollLeft;
  });

  stickyHeader.addEventListener('scroll', function() {
    tableContainer.scrollLeft = stickyHeader.scrollLeft;
  });
});

// 
(function () {
  function pms(s) { var a = s.split(/[- :]/); return Date.UTC(+a[0], +a[1] - 1, +a[2], +a[3] || 0, +a[4] || 0, +a[5] || 0); }
  function fmtUTC(ms) {
    var d = new Date(ms);
    function z(n) { return (n < 10 ? '0' : '') + n; }
    return d.getUTCFullYear() + '-' + z(d.getUTCMonth() + 1) + '-' + z(d.getUTCDate()) + ' ' + z(d.getUTCHours()) + ':' + z(d.getUTCMinutes()) + ':' + z(d.getUTCSeconds());
  }
  function rpcWrite(taskId, vals, cb) {
    fetch('/web/dataset/call_kw', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {
        model: 'project.task', method: 'write', args: [[taskId], vals], kwargs: {}
      }})
    }).then(function (r) { return r.json(); }).then(function (data) {
      if (data.error) { cb(false, data.error.data && data.error.data.message || data.error.message); }
      else { cb(true); }
    }).catch(function (e) { cb(false, String(e)); });
  }
  var dragged = null;
  function applyDrop(card, cell) {
    var taskId = parseInt(card.getAttribute('data-id'));
    var day = cell.getAttribute('data-day');
    var engin = parseInt(cell.getAttribute('data-engin'));
    var begin = card.getAttribute('data-begin');
    var fromBacklog = !begin;
    var time = begin ? begin.split(' ')[1] : '08:00:00';
    var newBegin = day + ' ' + time;
    var vals = { planned_date_begin: newBegin, x_studio_transport: engin > 0 ? engin : false };
    var end = card.getAttribute('data-end');
    if (end) { vals.date_deadline = fmtUTC(pms(newBegin) + (pms(end) - pms(begin))); }
    else if (fromBacklog) { vals.date_deadline = fmtUTC(pms(newBegin) + 3600000); }
    var origin = card.parentNode;
    cell.appendChild(card);
    card.setAttribute('data-begin', newBegin);
    if (vals.date_deadline) { card.setAttribute('data-end', vals.date_deadline); }
    rpcWrite(taskId, vals, function (ok, msg) {
      if (!ok) { origin.appendChild(card); alert('Échec : ' + msg); }
      else if (fromBacklog) { window.location.reload(); }
    });
  }
  var cards = document.querySelectorAll('.tp-card');
  for (var ci = 0; ci < cards.length; ci++) {
    (function (card) {
      card.addEventListener('click', function (ev) {
        if (ev.target.closest('a')) { return; }
        window.open('/web#id=' + card.getAttribute('data-id') + '&view_type=form&model=project.task', '_blank');
      });
      card.setAttribute('draggable', 'true');
      card.addEventListener('dragstart', function () { dragged = card; card.style.opacity = '0.4'; });
      card.addEventListener('dragend', function () { card.style.opacity = '1'; });
    })(cards[ci]);
  }
  var cells = document.querySelectorAll('.tp-cell');
  for (var co = 0; co < cells.length; co++) {
    (function (cell) {
      cell.addEventListener('dragover', function (ev) { ev.preventDefault(); cell.style.background = '#DBEAFE'; });
      cell.addEventListener('dragleave', function () { cell.style.background = ''; });
      cell.addEventListener('drop', function (ev) {
        ev.preventDefault(); cell.style.background = '';
        if (dragged) { applyDrop(dragged, cell); dragged = null; }
      });
    })(cells[co]);
  }
  setInterval(function () {
    var modals = document.querySelectorAll('.modal, .o_dialog');
    for (var i = 0; i < modals.length; i++) {
      if ((modals[i].textContent || '').indexOf('Could not start interaction') !== -1) {
        var btns = modals[i].querySelectorAll('button');
        for (var j = 0; j < btns.length; j++) {
          if (/fermer|close/i.test(btns[j].textContent || '')) { btns[j].click(); }
        }
      }
    }
  }, 1200);
})();
// 

window.fitGrid = function(){
  var el = document.querySelector('.tt-scroll');
  if(!el){ return; }
  var h = window.innerHeight - el.getBoundingClientRect().top - 8;
  el.style.maxHeight = Math.max(220, h) + 'px';
};
window.addEventListener('load', window.fitGrid);
window.addEventListener('resize', window.fitGrid);
setTimeout(window.fitGrid, 400);
